import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/physical-geography/hazards/","title":"CH1.3 灾害、污染与破坏 | 英语","lang":"zh-CN","frontmatter":{"title":"CH1.3 灾害、污染与破坏","createTime":"2026-11-18T09:50:00.000Z","permalink":"/english/vocabulary/physical-geography/hazards/"},"readingTime":{"minutes":34,"words":10201},"git":{"createdTime":1795010783000},"filePathRelative":"english/vocabulary/physical-geography/3.hazards-and-pollution.md","headers":[],"bulletin":false}`),a={name:`3.hazards-and-pollution.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="disaster" tabindex="-1"><a class="header-anchor" href="#disaster"><span>Disaster</span></a></h2><p class="vc-meta"><strong>/dɪˈzɑːstə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>灾难，灾害；彻底的失败</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>natural disaster</td><td>自然灾害</td></tr><tr><td>disaster relief</td><td>救灾</td></tr><tr><td>disaster prevention</td><td>防灾</td></tr><tr><td>a disaster area</td><td>灾区</td></tr><tr><td>end in disaster</td><td>以失败／灾难告终</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The table compares the economic losses caused by natural disasters in four countries.</p><blockquote><p>该表比较了四国自然灾害造成的经济损失。</p></blockquote><p><strong>Writing Task 2</strong> Investment in disaster prevention is far cheaper than rebuilding after a flood or an earthquake.</p><blockquote><p>投资防灾远比灾后重建更经济。</p></blockquote><p><strong>Speaking</strong> The trip turned into a disaster — we missed the ferry and then it rained for three days.</p><blockquote><p>那次旅行变成了一场灾难：我们错过了渡轮，接着又下了三天雨。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>catastrophe</td><td>大灾难</td><td>程度更重，多指大规模、不可逆的灾难</td></tr><tr><td>calamity</td><td>灾祸</td><td>书面且略旧，多指公共性的不幸</td></tr><tr><td>emergency</td><td>紧急情况</td><td>强调需立即应对，规模不一定大</td></tr><tr><td>hazard</td><td>隐患；危险源</td><td>指潜在危险，不是已经发生的灾害</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> dis-（否定、相反）+ aster（希腊语 <em>astron</em>，星辰）→ 原义&quot;星位不吉&quot;</li><li><strong>Family:</strong> astronomy 天文学 / asterisk 星号 / asteroid 小行星 / disastrous 灾难性的</li><li><strong>Memory Tip:</strong> dis + aster（星）= &quot;星星不吉&quot;。古人把灾祸归咎于星象，所以 disaster 字面就是&quot;星位错乱&quot;。同族的 astron 就是星星。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a disaster、two disasters；抽象表述可说 end in disaster。</li><li>形容词是 disastrous：a disastrous policy；<s>a disaster policy</s> ✘。</li><li>与 hazard 区分：hazard 是潜在危险源，disaster 是已经发生的灾害。</li><li>拼写 disaster 只有一个 s，别漏掉 -ster 里的 s。</li></ul></div><div class="vocab-card"><h2 id="mishap" tabindex="-1"><a class="header-anchor" href="#mishap"><span>Mishap</span></a></h2><p class="vc-meta"><strong>/ˈmɪshæp/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>小事故，不幸的意外（程度较轻）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a minor mishap</td><td>一次小意外</td></tr><tr><td>without mishap</td><td>平安无事地</td></tr><tr><td>a mishap at work</td><td>工作中的小差错</td></tr><tr><td>despite a few mishaps</td><td>尽管出了几次小岔子</td></tr><tr><td>a traffic mishap</td><td>轻微的交通意外</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the number of minor mishaps reported at three airports between 2015 and 2020.</p><blockquote><p>该图显示了 2015 至 2020 年间三个机场报告的轻微事故数量。</p></blockquote><p><strong>Writing Task 2</strong> A single mishap at a nuclear plant can outweigh years of routine compliance.</p><blockquote><p>核电站的一次小事故，可能抵消多年的例行合规努力。</p></blockquote><p><strong>Speaking</strong> The hike went smoothly apart from one mishap — I dropped my phone in the stream.</p><blockquote><p>徒步很顺利，只有一次小意外——我把手机掉进了小溪。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>accident</td><td>事故</td><td>中性通用，程度可轻可重</td></tr><tr><td>misfortune</td><td>不幸</td><td>范围更广，偏指运气不佳</td></tr><tr><td>incident</td><td>事件</td><td>官方用语，中性，不一定含&quot;意外&quot;义</td></tr><tr><td>setback</td><td>挫折</td><td>强调进展受挫，不是人身或设备事故</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> mis-（错、坏）+ hap（运气，古诺尔斯语 <em>happ</em>）</li><li><strong>Family:</strong> happen 发生 / perhaps 也许（per + hap&quot;凭运气&quot;）/ happy 快乐的（原义&quot;运气好&quot;）/ haphazard 偶然的</li><li><strong>Memory Tip:</strong> hap 就是&quot;运气&quot;：happy 本义&quot;运气好&quot;，perhaps 是&quot;凭运气&quot;所以&quot;也许&quot;。mis + hap 就是坏运气——一次小意外。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>程度很轻，别用来写地震、空难，那些要用 disaster / catastrophe。</li><li>可数：a minor mishap、several mishaps。</li><li>拼写 mishap 只有一个 p，别写成 <s>misshap</s>。</li></ul></div><div class="vocab-card"><h2 id="catastrophic" tabindex="-1"><a class="header-anchor" href="#catastrophic"><span>Catastrophic</span></a></h2><p class="vc-meta"><strong>/ˌkætəˈstrɒfɪk/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>灾难性的；造成巨大损失的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>catastrophic consequences</td><td>灾难性后果</td></tr><tr><td>a catastrophic failure</td><td>灾难性故障</td></tr><tr><td>catastrophic flooding</td><td>灾难性洪灾</td></tr><tr><td>potentially catastrophic</td><td>可能造成灾难的</td></tr><tr><td>catastrophic loss of life</td><td>惨重的人员伤亡</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map illustrates the catastrophic extent of coastal erosion between 1990 and 2020.</p><blockquote><p>该地图展示了 1990 至 2020 年间海岸侵蚀的灾难性程度。</p></blockquote><p><strong>Writing Task 2</strong> For low-lying island states, a one-metre rise in sea level would be catastrophic rather than merely inconvenient.</p><blockquote><p>对低洼岛国而言，海平面上升一米是灾难性的，而不只是不便。</p></blockquote><p><strong>Speaking</strong> The flood was catastrophic for the village — half the houses were simply gone.</p><blockquote><p>那场洪水对村子来说是灾难性的，一半的房子直接没了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>disastrous</td><td>灾难性的</td><td>最接近，语域略轻</td></tr><tr><td>devastating</td><td>毁灭性的</td><td>强调破坏力与情感冲击</td></tr><tr><td>calamitous</td><td>灾难性的</td><td>极为书面，日常少用</td></tr><tr><td>ruinous</td><td>导致破产的</td><td>多用于经济、财政后果</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> cata-（向下、彻底）+ strophe（转，希腊语 <em>strephein</em>）→ 原义&quot;急转直下&quot;</li><li><strong>Family:</strong> catastrophe 大灾难 / apostrophe 撇号（原义&quot;转开&quot;）/ catastrophic 灾难性的</li><li><strong>Memory Tip:</strong> cata 向下 + strophe 转 = 急转直下。古希腊悲剧结尾的突转就叫 catastrophe，引申为&quot;灭顶之灾&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>是形容词，不能单独当名词：a catastrophic event ✔ / <s>a catastrophic</s> ✘。</li><li>程度排序：minor → serious → disastrous → catastrophic，别在小事故上用。</li><li>结尾是 -ic：<s>catastrophical</s> 几乎不用。</li></ul></div><div class="vocab-card"><h2 id="calamity" tabindex="-1"><a class="header-anchor" href="#calamity"><span>Calamity</span></a></h2><p class="vc-meta"><strong>/kəˈlæməti/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>灾祸，不幸事件（正式，多指影响公共的灾祸）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a natural calamity</td><td>自然灾害</td></tr><tr><td>suffer a calamity</td><td>遭遇灾祸</td></tr><tr><td>a national calamity</td><td>国难</td></tr><tr><td>avert a calamity</td><td>避免一场灾祸</td></tr><tr><td>the aftermath of a calamity</td><td>灾后余波</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The table lists the economic cost of major calamities in the region since 1980.</p><blockquote><p>该表列出了该地区自 1980 年以来重大灾祸的经济损失。</p></blockquote><p><strong>Writing Task 2</strong> Governments rarely budget for calamities until one has already struck.</p><blockquote><p>政府很少在灾祸真正发生之前就为其编列预算。</p></blockquote><p><strong>Speaking</strong> The whole harvest failed — for a farming family that&#39;s a calamity, not just bad luck.</p><blockquote><p>整季收成没了——对农户来说这是灾祸，不只是运气差。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>disaster</td><td>灾难</td><td>最通用，口语书面皆可</td></tr><tr><td>catastrophe</td><td>大灾难</td><td>程度更重，强调不可逆</td></tr><tr><td>misfortune</td><td>不幸</td><td>偏个人运气层面</td></tr><tr><td>adversity</td><td>逆境</td><td>强调持续性的困难处境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>calamitas</em>（损害、灾祸）</li><li><strong>Family:</strong> calamitous 灾难性的 / calamity 灾祸</li><li><strong>Memory Tip:</strong> 与 disaster 同义，但语域更书面、更&quot;公共&quot;。灾难报道里常见 a calamity of immense proportions 这类说法。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>语域偏正式甚至略旧，日常口语用 disaster 更自然。</li><li>可数：a calamity、calamities；别当不可数用。</li><li>拼写 calamity 中间是 -lam-，与 celebrity（名人）只是形近，意思无关。</li></ul></div><div class="vocab-card"><h2 id="endanger" tabindex="-1"><a class="header-anchor" href="#endanger"><span>Endanger</span></a></h2><p class="vc-meta"><strong>/ɪnˈdeɪndʒə(r)/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>危及，使……遭到危险</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>endangered species</td><td>濒危物种</td></tr><tr><td>endanger public health</td><td>危害公众健康</td></tr><tr><td>seriously endanger</td><td>严重危及</td></tr><tr><td>endanger the survival of</td><td>危及……的生存</td></tr><tr><td>endanger marine life</td><td>危及海洋生物</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how many species were classified as endangered in each region in 2020.</p><blockquote><p>该图显示了 2020 年各区域被列为濒危的物种数量。</p></blockquote><p><strong>Writing Task 2</strong> Unregulated tourism can endanger the very wildlife that visitors come to see.</p><blockquote><p>缺乏监管的旅游业可能危及游客专程前来观赏的野生动物。</p></blockquote><p><strong>Speaking</strong> Building a road through the forest would endanger the last few tigers in the area.</p><blockquote><p>在森林里修路会危及该地区仅存的几只老虎。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>threaten</td><td>威胁</td><td>最通用，威胁来源可具体可抽象</td></tr><tr><td>jeopardise</td><td>危及</td><td>多用于机会、成功等抽象事物</td></tr><tr><td>compromise</td><td>损害</td><td>强调削弱而非毁灭</td></tr><tr><td>imperil</td><td>危及</td><td>极为正式，书面语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> en-（使……）+ danger（危险）</li><li><strong>Family:</strong> danger 危险 / dangerous 危险的 / endangered 濒危的 / endangerment 危害（法律用语）</li><li><strong>Memory Tip:</strong> en- + 名词 = 动词（enslave 奴役、enrich 使富有）。所以 endanger 就是&quot;使陷入危险&quot;；endangered 是被危及的状态，濒危物种固定用这个被动形式。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物动词，必须带宾语：Human activity endangers wildlife ✔ / <s>Wildlife endangers</s> ✘。</li><li>濒危物种是 endangered species，不是 <s>endangering species</s>。</li><li>拼写 endanger，不是 <s>indanger</s>。</li></ul></div><div class="vocab-card"><h2 id="jeopardise" tabindex="-1"><a class="header-anchor" href="#jeopardise"><span>Jeopardise</span></a></h2><p class="vc-meta"><strong>/ˈdʒepədaɪz/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>危及，损害（多指机会、成功、关系等抽象事物）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>jeopardise one&#39;s chances</td><td>危及某人的机会</td></tr><tr><td>jeopardise the success of</td><td>危及……的成功</td></tr><tr><td>jeopardise public trust</td><td>损害公众信任</td></tr><tr><td>jeopardise a deal</td><td>危及一笔交易</td></tr><tr><td>seriously jeopardise</td><td>严重危及</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the number of projects jeopardised by funding cuts across three sectors.</p><blockquote><p>该图比较了三个行业中因经费削减而受威胁的项目数量。</p></blockquote><p><strong>Writing Task 2</strong> Cutting research funding would jeopardise the country&#39;s long-term competitiveness.</p><blockquote><p>削减科研经费会危及该国的长期竞争力。</p></blockquote><p><strong>Speaking</strong> I didn&#39;t want to jeopardise our friendship by bringing up the money issue again.</p><blockquote><p>我不想再提钱的事，以免损害我们的友谊。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>endanger</td><td>危及</td><td>多指生命、物种等实体风险</td></tr><tr><td>threaten</td><td>威胁</td><td>通用，可指人、机会、安全</td></tr><tr><td>compromise</td><td>损害</td><td>强调削弱品质或原则</td></tr><tr><td>risk</td><td>冒……的风险</td><td>主语是主动承担者，语义不同</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> jeopardy（危险，古法语 <em>jeu parti</em>&quot;胜负未定的赌局&quot;）+ -ise（英式动词后缀）</li><li><strong>Family:</strong> jeopardy 危险 / jeopardise（英式）/ jeopardize（美式）</li><li><strong>Memory Tip:</strong> 美国电视问答节目 Jeopardy（危险边缘）用的就是这个字——答错就&quot;身陷险境&quot;。jeu parti 原义是胜负未分的赌局。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式拼 -ise，美式拼 -ize；同一份文档里保持一致，别混写。</li><li>多接抽象宾语（机会、声誉、关系）；讲生命危险用 endanger 更自然。</li><li>及物动词，必须有宾语：<s>The plan jeopardises</s> 缺宾语时要用被动 be jeopardised。</li></ul></div><div class="vocab-card"><h2 id="destructive" tabindex="-1"><a class="header-anchor" href="#destructive"><span>Destructive</span></a></h2><p class="vc-meta"><strong>/dɪˈstrʌktɪv/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>破坏性的，毁灭性的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>destructive behaviour</td><td>破坏性行为</td></tr><tr><td>environmentally destructive</td><td>对环境有破坏性的</td></tr><tr><td>destructive fishing methods</td><td>破坏性捕捞方式</td></tr><tr><td>destructive power</td><td>破坏力</td></tr><tr><td>destructive to</td><td>对……有破坏性</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the destructive path of the tornado across three counties.</p><blockquote><p>该地图显示了龙卷风横穿三个县的破坏路径。</p></blockquote><p><strong>Writing Task 2</strong> Bottom trawling is one of the most destructive forms of fishing, tearing up seabed habitats that take decades to recover.</p><blockquote><p>底拖网是最具破坏性的捕捞方式之一，会撕裂需要数十年才能恢复的海底栖息地。</p></blockquote><p><strong>Speaking</strong> What surprised me was how destructive a single storm could be to a coral reef.</p><blockquote><p>让我意外的是，一场风暴对珊瑚礁的破坏能有多大。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>damaging</td><td>有害的</td><td>程度较轻，强调造成损害</td></tr><tr><td>devastating</td><td>毁灭性的</td><td>程度更重，含情感冲击</td></tr><tr><td>ruinous</td><td>导致毁灭的</td><td>多用于经济、财政后果</td></tr><tr><td>harmful</td><td>有害的</td><td>最轻，多指健康与环境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> de-（向下、去除）+ struct（建造，拉丁语 <em>struere</em>）+ -ive（形容词后缀）</li><li><strong>Family:</strong> destroy 摧毁 / destruction 破坏 / construct 建造 / instruct 指导 / structure 结构</li><li><strong>Memory Tip:</strong> struct 是&quot;建造&quot;（structure、construct、instruct 全是这个根）。de- 表示&quot;反、去掉&quot;，所以 destructive 字面就是&quot;反建造&quot;——把建好的拆掉。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>搭配介词 to：destructive <strong>to</strong> the environment，不用 <s>destructive for</s>。</li><li>程度比 damaging 重，小范围损坏别用它。</li><li>拼写 destructive 结尾 -ive，不是 <s>destructuve</s>。</li></ul></div><div class="vocab-card"><h2 id="el-nino" tabindex="-1"><a class="header-anchor" href="#el-nino"><span>El Niño</span></a></h2><p class="vc-meta"><strong>/el ˈniːnjəʊ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>厄尔尼诺现象（赤道太平洋中东部海水异常增温）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a strong El Niño</td><td>强厄尔尼诺</td></tr><tr><td>El Niño years</td><td>厄尔尼诺年</td></tr><tr><td>El Niño conditions</td><td>厄尔尼诺状态</td></tr><tr><td>El Niño events</td><td>厄尔尼诺事件</td></tr><tr><td>the El Niño phenomenon</td><td>厄尔尼诺现象</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph compares rainfall in Peru during El Niño and La Niña years.</p><blockquote><p>该图比较了厄尔尼诺年与拉尼娜年秘鲁的降水量。</p></blockquote><p><strong>Writing Task 2</strong> A strong El Niño can push global average temperatures to record highs and trigger droughts thousands of kilometres away.</p><blockquote><p>强厄尔尼诺会把全球平均气温推至历史高点，并在数千公里之外引发干旱。</p></blockquote><p><strong>Speaking</strong> Our teacher used El Niño to explain how the ocean and the atmosphere are connected.</p><blockquote><p>老师用厄尔尼诺来解释海洋与大气是如何相互联系的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>La Niña</td><td>拉尼娜</td><td>相反相位，海水异常偏冷</td></tr><tr><td>ENSO</td><td>厄尔尼诺—南方涛动</td><td>学术总称，涵盖两个相位</td></tr><tr><td>climate anomaly</td><td>气候异常</td><td>泛指，不特指这一现象</td></tr><tr><td>ocean current shift</td><td>洋流变化</td><td>描述机制，不是术语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 西班牙语 <em>El Niño</em>（小男孩），因常在圣诞节前后出现于秘鲁外海而得名；对应 <em>La Niña</em>（小女孩）</li><li><strong>Family:</strong> La Niña 拉尼娜 / ENSO 厄尔尼诺—南方涛动</li><li><strong>Memory Tip:</strong> 秘鲁渔民发现海水每隔几年就在圣诞前后变暖，随口叫它&quot;小男孩&quot;。一个渔民的绰号，如今成了正式气候术语。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>专有名词，首字母大写且分开写：<s>Elniño</s> ✘。</li><li>一般不加冠词：during El Niño；只有 the El Niño phenomenon 这种结构才加 the。</li><li>保留西班牙语的 ñ，别写成 <s>Nino</s>（英文排版中偶尔省略波浪号，但正式文本保留）。</li><li>复数用 El Niño events，不写 <s>El Niños</s>。</li></ul></div><div class="vocab-card"><h2 id="greenhouse" tabindex="-1"><a class="header-anchor" href="#greenhouse"><span>Greenhouse</span></a></h2><p class="vc-meta"><strong>/ˈɡriːnhaʊs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>温室，暖房；（作定语）温室效应的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>greenhouse gases</td><td>温室气体</td></tr><tr><td>the greenhouse effect</td><td>温室效应</td></tr><tr><td>greenhouse gas emissions</td><td>温室气体排放</td></tr><tr><td>grow tomatoes in a greenhouse</td><td>在温室里种番茄</td></tr><tr><td>greenhouse warming</td><td>温室效应导致的升温</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows greenhouse gas emissions by sector in 2020.</p><blockquote><p>该图显示了 2020 年各行业的温室气体排放量。</p></blockquote><p><strong>Writing Task 2</strong> Agriculture accounts for a substantial share of greenhouse gas emissions, largely through methane from livestock.</p><blockquote><p>农业在温室气体排放中占相当大的比重，主要来自牲畜排放的甲烷。</p></blockquote><p><strong>Speaking</strong> My grandmother grows cucumbers in a small greenhouse at the back of her garden.</p><blockquote><p>我奶奶在花园后面的小温室里种黄瓜。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>glasshouse</td><td>温室</td><td>英式同义词，多指大型观赏温室</td></tr><tr><td>conservatory</td><td>玻璃暖房</td><td>附在住宅上的那种</td></tr><tr><td>hothouse</td><td>暖房</td><td>强调高温培育，也比喻&quot;温室环境&quot;</td></tr><tr><td>the greenhouse effect</td><td>温室效应</td><td>是现象，不是建筑</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> green（绿）+ house（房子）→ 玻璃房留住热量 → 比喻大气层像温室</li><li><strong>Family:</strong> greenhouse effect 温室效应 / greenhouse gas 温室气体 / hothouse 暖房</li><li><strong>Memory Tip:</strong> 温室玻璃让阳光进来、把热量留住；大气中的二氧化碳做的是同一件事，所以叫 greenhouse effect。一个农业词汇变成了气候术语。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作定语时用单数：greenhouse gases，不是 <s>greenhouses gases</s>。</li><li>温室效应是 the greenhouse effect，冠词不能省。</li><li>连写成一个词：<s>green house</s> 指&quot;绿色的房子&quot;，是另一个意思。</li></ul></div><div class="vocab-card"><h2 id="phenomenon" tabindex="-1"><a class="header-anchor" href="#phenomenon"><span>Phenomenon</span></a></h2><p class="vc-meta"><strong>/fəˈnɒmɪnən/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>现象；非凡的人（或事物）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a natural phenomenon</td><td>自然现象</td></tr><tr><td>a rare phenomenon</td><td>罕见现象</td></tr><tr><td>a global phenomenon</td><td>全球性现象</td></tr><tr><td>explain the phenomenon</td><td>解释这一现象</td></tr><tr><td>a cultural phenomenon</td><td>文化现象</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram illustrates the phenomenon of coastal upwelling along the Peruvian coast.</p><blockquote><p>该图说明了秘鲁沿岸的上升流现象。</p></blockquote><p><strong>Writing Task 2</strong> Urbanisation is a global phenomenon, but its pace varies enormously between regions.</p><blockquote><p>城市化是全球性现象，但其速度在各地区差异极大。</p></blockquote><p><strong>Speaking</strong> The northern lights are the one natural phenomenon I&#39;d really like to see in person.</p><blockquote><p>极光是我最想亲眼看到的自然现象。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>occurrence</td><td>发生的事</td><td>中性，不含&quot;值得研究&quot;的意味</td></tr><tr><td>event</td><td>事件</td><td>通用，无学术色彩</td></tr><tr><td>spectacle</td><td>壮观景象</td><td>强调视觉冲击</td></tr><tr><td>epiphenomenon</td><td>副现象</td><td>专业术语，指附带产生的现象</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> phaino-（希腊语&quot;显现&quot;）+ -menon（分词后缀）→ &quot;显现出来的东西&quot;</li><li><strong>Family:</strong> phenomena（复数）/ phenomenal 非凡的 / phantom 幻影 / fantasy 幻想 / phase 相位</li><li><strong>Memory Tip:</strong> phain 就是&quot;显形&quot;：phantom 是显现的影，phenomenal 是&quot;显现得惊人&quot;所以非凡。凡是&quot;显现出来可供观察的事&quot;，都是 phenomenon。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li><strong>复数是 phenomena</strong>：a phenomenon / two phenomena；<s>phenomenons</s> ✘。</li><li>可数，单数要带冠词：a natural phenomenon。</li><li>拼写中间是 -menon，不是 <s>-minon</s>。</li></ul></div><div class="vocab-card"><h2 id="tsunami" tabindex="-1"><a class="header-anchor" href="#tsunami"><span>Tsunami</span></a></h2><p class="vc-meta"><strong>/tsuːˈnɑːmi/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>海啸</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a tsunami warning</td><td>海啸预警</td></tr><tr><td>a tsunami struck the coast</td><td>海啸袭击海岸</td></tr><tr><td>tsunami waves</td><td>海啸波</td></tr><tr><td>a tsunami triggered by an earthquake</td><td>地震引发的海啸</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how far the 2004 tsunami reached along the coastlines of the Indian Ocean.</p><blockquote><p>该地图显示了 2004 年海啸在印度洋沿岸波及的范围。</p></blockquote><p><strong>Writing Task 2</strong> Mangrove forests absorb much of a tsunami&#39;s energy before it reaches inhabited land.</p><blockquote><p>红树林能在海啸抵达居民区之前吸收其大部分能量。</p></blockquote><p><strong>Speaking</strong> The town rebuilt with a wall along the shore after the tsunami, but nobody swims there now.</p><blockquote><p>海啸之后小镇在岸边修了防波墙，但现在没人去那儿游泳了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>seismic sea wave</td><td>地震海浪</td><td>专业术语，学术文本可见</td></tr><tr><td>tidal wave</td><td>潮波</td><td>常见误称，成因并非潮汐</td></tr><tr><td>storm surge</td><td>风暴潮</td><td>由风暴引起，不是地震</td></tr><tr><td>flood</td><td>洪水</td><td>泛指，不含成因</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 日语 津（<em>tsu</em>，港口）+ 波（<em>nami</em>，浪）→ &quot;港口的浪&quot;</li><li><strong>Family:</strong> tsunamis（复数，英语中不加 -es）</li><li><strong>Memory Tip:</strong> 为什么叫&quot;港口的浪&quot;？因为船在深港内毫无感觉，浪却在港口造成破坏——海啸在深海几乎不可见，靠岸才骤然升高。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>别用 tidal wave 代替，那是错误成因的叫法。</li><li>复数 tsunamis，不加 -es。</li><li>元音开头用 a tsunami（/ts/ 是辅音，读作&quot;促&quot;，用 a 正确）。</li></ul></div><div class="vocab-card"><h2 id="drought" tabindex="-1"><a class="header-anchor" href="#drought"><span>Drought</span></a></h2><p class="vc-meta"><strong>/draʊt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>旱灾，长期缺水</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a severe drought</td><td>严重旱灾</td></tr><tr><td>drought-resistant crops</td><td>抗旱作物</td></tr><tr><td>a period of drought</td><td>干旱期</td></tr><tr><td>drought conditions</td><td>干旱状况</td></tr><tr><td>drought relief</td><td>抗旱救灾</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph compares rainfall and drought frequency in the region from 1970 to 2020.</p><blockquote><p>该图比较了该地区 1970 至 2020 年的降水与干旱频次。</p></blockquote><p><strong>Writing Task 2</strong> Successive droughts have forced farmers to abandon crops that need irrigation.</p><blockquote><p>连年干旱迫使农民放弃需要灌溉的作物。</p></blockquote><p><strong>Speaking</strong> That summer there was a drought, and the reservoir dropped to half its size.</p><blockquote><p>那年夏天闹旱灾，水库缩小了一半。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>dry spell</td><td>干旱期</td><td>时间较短，程度较轻</td></tr><tr><td>aridity</td><td>干燥</td><td>气候状态，不是一次灾害</td></tr><tr><td>water shortage</td><td>缺水</td><td>结果描述，成因可为人或气候</td></tr><tr><td>famine</td><td>饥荒</td><td>是后果，不是原因</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>drugian</em>（变干），与 dry 同源</li><li><strong>Family:</strong> dry 干的 / droughty 干旱的 / drought-resistant 抗旱的</li><li><strong>Memory Tip:</strong> dry 与 drought 是同一个 dr- 家族，一个是形容词，一个是那次&quot;干&quot;成灾的事件。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a drought、several droughts。</li><li>与 dry season 区分：后者是气候常态，drought 是异常且造成损失的。</li><li>拼写 drought 中间是 -ough-，读 /draʊt/，别写成 <s>drougt</s>。</li></ul></div><div class="vocab-card"><h2 id="flooding" tabindex="-1"><a class="header-anchor" href="#flooding"><span>Flooding</span></a></h2><p class="vc-meta"><strong>/ˈflʌdɪŋ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>洪涝，泛滥，被水淹没</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>widespread flooding</td><td>大范围洪涝</td></tr><tr><td>flash flooding</td><td>山洪暴发</td></tr><tr><td>coastal flooding</td><td>沿海洪涝</td></tr><tr><td>flooding caused by heavy rain</td><td>暴雨引发的洪涝</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows areas at risk of flooding if sea levels rise by one metre.</p><blockquote><p>该地图显示了海平面上升一米时面临洪涝风险的区域。</p></blockquote><p><strong>Writing Task 2</strong> Paving over wetlands removes natural sponges and makes flooding more likely downstream.</p><blockquote><p>把湿地铺成硬地，等于拆掉了天然海绵，使下游更易发生洪涝。</p></blockquote><p><strong>Speaking</strong> After the storm, flooding closed the main road for three days.</p><blockquote><p>暴风雨过后，洪水把主路封了三天。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>flood</td><td>洪水</td><td>可数，指一次具体洪水</td></tr><tr><td>inundation</td><td>淹没</td><td>书面语，强调被水覆盖</td></tr><tr><td>deluge</td><td>暴雨；洪水</td><td>文学色彩强</td></tr><tr><td>torrent</td><td>急流</td><td>强调水流湍急，不是淹没范围</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> flood（洪水）+ -ing（名词化）→ 强调&quot;泛滥&quot;的过程与状态</li><li><strong>Family:</strong> flood 洪水 / floodplain 洪泛平原 / floodgate 泄洪闸</li><li><strong>Memory Tip:</strong> 写作里描述灾害范围用不可数的 flooding 更自然（widespread flooding），指某一次洪水才用可数的 a flood。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>flooding 不可数：<s>floodings</s> ✘。</li><li>与 flood 区分：flood 可数（two floods），flooding 不可数。</li><li>搭配 risk of flooding，不用 <s>risk of flood</s>。</li></ul></div><div class="vocab-card"><h2 id="torrent" tabindex="-1"><a class="header-anchor" href="#torrent"><span>Torrent</span></a></h2><p class="vc-meta"><strong>/ˈtɒrənt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>急流，奔流；（言语等的）连发</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mountain torrent</td><td>山间急流</td></tr><tr><td>torrential rain</td><td>倾盆大雨</td></tr><tr><td>a torrent of abuse</td><td>一连串辱骂</td></tr><tr><td>a torrent of water</td><td>一股急流</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how a mountain torrent carries sediment down to the plain.</p><blockquote><p>该图显示了山间急流如何把沉积物搬运到平原。</p></blockquote><p><strong>Writing Task 2</strong> Deforestation turns gentle streams into torrents after heavy rain.</p><blockquote><p>森林砍伐使得暴雨之后平缓的溪流变成急流。</p></blockquote><p><strong>Speaking</strong> After the storm the path became a torrent — we had to turn back.</p><blockquote><p>暴雨过后小路变成了一条急流，我们只好折返。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>stream</td><td>溪流</td><td>平缓，规模小</td></tr><tr><td>rapids</td><td>急流段</td><td>指河流中湍急的一段</td></tr><tr><td>cascade</td><td>小瀑布</td><td>强调落差</td></tr><tr><td>deluge</td><td>洪水</td><td>强调水量与范围</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>torrens</em>（沸腾的、奔流的），与 torrid（炎热的）同源</li><li><strong>Family:</strong> torrential 倾盆的 / torrent 急流</li><li><strong>Memory Tip:</strong> 原义是&quot;沸腾翻滚的水&quot;，所以 torrential rain 就是&quot;下得像开水翻滚&quot;的雨——倾盆大雨。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a torrent、torrents。</li><li>形容词是 torrential：torrential rain，不说 <s>torrent rain</s>。</li><li>拼写 torrent 双 r 双 t。</li></ul></div><div class="vocab-card"><h2 id="earthquake" tabindex="-1"><a class="header-anchor" href="#earthquake"><span>Earthquake</span></a></h2><p class="vc-meta"><strong>/ˈɜːθkweɪk/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>地震</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a devastating earthquake</td><td>毁灭性地震</td></tr><tr><td>an earthquake struck</td><td>地震发生</td></tr><tr><td>earthquake-resistant buildings</td><td>抗震建筑</td></tr><tr><td>the magnitude of an earthquake</td><td>地震震级</td></tr><tr><td>aftershock</td><td>余震</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map marks the epicentres of earthquakes recorded in the region since 1950.</p><blockquote><p>该图标出了该地区自 1950 年以来记录到的地震震中。</p></blockquote><p><strong>Writing Task 2</strong> Earthquake-resistant design adds perhaps five per cent to construction costs but saves lives.</p><blockquote><p>抗震设计大约增加 5% 的建造成本，却能挽救生命。</p></blockquote><p><strong>Speaking</strong> I was in Tokyo when a small earthquake hit — the building swayed and everyone kept eating.</p><blockquote><p>东京那次小地震时我在场，楼在晃，大家继续吃饭。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>quake</td><td>地震</td><td>口语与新闻标题常用</td></tr><tr><td>tremor</td><td>微震</td><td>强度小，常指前震余震</td></tr><tr><td>seismic activity</td><td>地震活动</td><td>学术表述，含各种震动</td></tr><tr><td>shock</td><td>震动</td><td>泛指，需上下文限定</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> earth（地）+ quake（震动，古英语 <em>cwacian</em>）</li><li><strong>Family:</strong> quake 颤抖；地震 / earthquake-prone 地震多发的 / aftershock 余震</li><li><strong>Memory Tip:</strong> 字面就是&quot;地动&quot;。记住 quake = 颤抖，就能理解 earthquake、quake、以及&quot;quaking with fear&quot;（吓得发抖）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>用 an earthquake（元音开头）。</li><li>震级说 magnitude 7.0，不说 <s>7.0 level</s>（Richter scale 是旧表述）。</li><li>可数：a strong earthquake、two earthquakes。</li></ul></div><div class="vocab-card"><h2 id="seismic" tabindex="-1"><a class="header-anchor" href="#seismic"><span>Seismic</span></a></h2><p class="vc-meta"><strong>/ˈsaɪzmɪk/</strong> · adjective · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>地震的，地震引起的；（比喻）影响深远的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>seismic activity</td><td>地震活动</td></tr><tr><td>seismic waves</td><td>地震波</td></tr><tr><td>a seismic survey</td><td>地震勘测</td></tr><tr><td>seismic zones</td><td>地震带</td></tr><tr><td>a seismic shift</td><td>根本性转变</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map divides the country into seismic zones according to the risk of strong ground shaking.</p><blockquote><p>该地图按强地面震动风险把全国划分为不同地震带。</p></blockquote><p><strong>Writing Task 2</strong> The shift to remote work was a seismic change in how cities function.</p><blockquote><p>远程办公的兴起是城市运转方式上的一次根本性转变。</p></blockquote><p><strong>Speaking</strong> The building is old but it survived because it sits on solid rock, away from seismic faults.</p><blockquote><p>那栋楼很老却安然无恙，因为它建在坚实岩层上，远离地震断层。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tectonic</td><td>构造的</td><td>指板块构造，不直接等于地震</td></tr><tr><td>earthquake-related</td><td>与地震有关的</td><td>描述性说法，冗长</td></tr><tr><td>momentous</td><td>重大的</td><td>只对应比喻义</td></tr><tr><td>radical</td><td>根本的</td><td>只对应比喻义，不含地震</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>seismos</em>（震动）+ -ic</li><li><strong>Family:</strong> seismograph 地震仪 / seismology 地震学 / seismologist 地震学家</li><li><strong>Memory Tip:</strong> seismo- 就是&quot;震动&quot;。seismograph 是&quot;震动记录仪&quot;，seismic 是&quot;震动的&quot;，同根同源。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词，不能单独当名词：<s>a seismic</s> ✘。</li><li>seismic shift 是比喻用法，指&quot;根本性变化&quot;，不只是地质义。</li><li>拼写 seismic 中间是 -eis-，不是 <s>-ies-</s>。</li></ul></div><div class="vocab-card"><h2 id="avalanche" tabindex="-1"><a class="header-anchor" href="#avalanche"><span>Avalanche</span></a></h2><p class="vc-meta"><strong>/ˈævəlɑːnʃ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>雪崩；（大量涌来的）洪流</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an avalanche warning</td><td>雪崩预警</td></tr><tr><td>trigger an avalanche</td><td>引发雪崩</td></tr><tr><td>be buried by an avalanche</td><td>被雪崩掩埋</td></tr><tr><td>an avalanche of</td><td>大量的（比喻）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows avalanche risk zones along the mountain pass.</p><blockquote><p>该地图显示了山口沿线的雪崩风险区。</p></blockquote><p><strong>Writing Task 2</strong> Warmer winters make avalanches both more frequent and harder to predict.</p><blockquote><p>更暖的冬季使雪崩既更频繁，也更难预测。</p></blockquote><p><strong>Speaking</strong> They closed the road because of avalanche risk — we waited two days in the village.</p><blockquote><p>因为雪崩风险封了路，我们在村里等了两天。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>landslide</td><td>滑坡</td><td>土石下滑，不是雪</td></tr><tr><td>rockfall</td><td>落石</td><td>岩石崩落，规模更小</td></tr><tr><td>snowslide</td><td>雪崩</td><td>字面直译，实际少用</td></tr><tr><td>deluge</td><td>大量涌来</td><td>只对应比喻义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>avaler</em>（向下吞）+ -anche → &quot;吞下去的东西&quot;</li><li><strong>Family:</strong> avalanche 雪崩 / avalanche-prone 易发雪崩的</li><li><strong>Memory Tip:</strong> avaler 是&quot;吞&quot;，雪崩就是山把沿途一切吞下去。比喻义 an avalanche of emails 就是&quot;邮件像雪崩一样涌来&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>用 an avalanche（/æ/ 元音开头）。</li><li>与 landslide 区分：一个是雪，一个是土石。</li><li>拼写 avalanche 结尾是 -che，不是 <s>-nsh</s>。</li></ul></div><div class="vocab-card"><h2 id="toxic" tabindex="-1"><a class="header-anchor" href="#toxic"><span>Toxic</span></a></h2><p class="vc-meta"><strong>/ˈtɒksɪk/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>有毒的（物质）</li><li>极有害的（关系、环境、文化）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>toxic waste</td><td>有毒废物</td></tr><tr><td>toxic chemicals</td><td>有毒化学品</td></tr><tr><td>toxic gas</td><td>毒气</td></tr><tr><td>a toxic relationship</td><td>有害的关系</td></tr><tr><td>toxic culture</td><td>有毒的文化氛围</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how toxic waste leaches into groundwater.</p><blockquote><p>该示意图显示了有毒废物如何渗入地下水。</p></blockquote><p><strong>Writing Task 2</strong> Toxic algal blooms are spreading as water temperatures rise.</p><blockquote><p>随着水温上升，有毒藻华正在扩散。</p></blockquote><p><strong>Speaking</strong> The fumes are toxic — don&#39;t go in without a mask.</p><blockquote><p>那些烟雾有毒，不戴口罩别进去。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>poisonous</td><td>有毒的</td><td>通用，可形容动植物</td></tr><tr><td>noxious</td><td>有害的</td><td>多指气体、气味</td></tr><tr><td>venomous</td><td>分泌毒液的</td><td>专指蛇、蝎等生物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>toxikon</em>（箭上的毒）← <em>toxon</em>（弓）</li><li><strong>Family:</strong> toxic 有毒的 / toxin 毒素 / toxicity 毒性 / detox 排毒</li><li><strong>Memory Tip:</strong> toxon = 弓，toxikon 是&quot;涂在箭头上的毒&quot;，所以 toxic 泛指&quot;有毒&quot;。而 venomous 专指生物自己分泌毒液（蛇、蝎）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容有毒动物用 venomous，不用 toxic。</li><li>名词是 toxicity（毒性），不是 <s>toxicness</s>。</li><li>抽象用法很常见：a toxic atmosphere / culture，写作里能用出彩。</li></ul></div><div class="vocab-card"><h2 id="pollution" tabindex="-1"><a class="header-anchor" href="#pollution"><span>Pollution</span></a></h2><p class="vc-meta"><strong>/pəˈluːʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>污染（状态、现象）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>air pollution</td><td>空气污染</td></tr><tr><td>water pollution</td><td>水污染</td></tr><tr><td>noise pollution</td><td>噪声污染</td></tr><tr><td>pollution levels</td><td>污染水平</td></tr><tr><td>reduce pollution</td><td>减少污染</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows pollution levels falling after the clean-air policy was introduced.</p><blockquote><p>该图表显示清洁空气政策出台后污染水平下降。</p></blockquote><p><strong>Writing Task 2</strong> Air pollution is now the largest environmental risk to public health worldwide.</p><blockquote><p>空气污染现已成为全球公共卫生面临的最大环境风险。</p></blockquote><p><strong>Speaking</strong> The pollution in that city is so bad you can actually taste it.</p><blockquote><p>那个城市的污染严重到能尝出味道。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>contamination</td><td>污染</td><td>更技术，强调外来物侵入</td></tr><tr><td>emissions</td><td>排放物</td><td>指排出物本身</td></tr><tr><td>degradation</td><td>退化</td><td>指环境质量下降</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>polluere</em>（弄脏）</li><li><strong>Family:</strong> pollution 污染 / pollute 污染（动词）/ pollutant 污染物 / polluter 污染者</li><li><strong>Memory Tip:</strong> 三件套一起记：pollute 是动作、pollution 是状态、pollutant 是物质。写作里混用这三者是最常见的失分点之一。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a pollution</s> 或 <s>pollutions</s>（除非指多类污染）。</li><li>air pollution 前不加 the。</li><li>pollution（状态）与 pollutant（物质）要分清。</li></ul></div><div class="vocab-card"><h2 id="pollutant" tabindex="-1"><a class="header-anchor" href="#pollutant"><span>Pollutant</span></a></h2><p class="vc-meta"><strong>/pəˈluːtənt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>污染物（具体的污染物质）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>air pollutants</td><td>空气污染物</td></tr><tr><td>pollutant emissions</td><td>污染物排放</td></tr><tr><td>release pollutants</td><td>释放污染物</td></tr><tr><td>a harmful pollutant</td><td>有害污染物</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares emissions of four major air pollutants over a decade.</p><blockquote><p>该图表比较了十年间四种主要空气污染物的排放量。</p></blockquote><p><strong>Writing Task 2</strong> Diesel vehicles are a major source of particulate pollutants in cities.</p><blockquote><p>柴油车是城市颗粒污染物的主要来源之一。</p></blockquote><p><strong>Speaking</strong> The factory releases pollutants into the river every night.</p><blockquote><p>那家工厂每晚都往河里排放污染物。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>contaminant</td><td>污染物</td><td>强调混入外来杂质</td></tr><tr><td>toxin</td><td>毒素</td><td>特指生物性毒物</td></tr><tr><td>emission</td><td>排放物</td><td>强调&quot;被排出&quot;这一动作结果</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>pollute</em>（污染）+ <em>-ant</em>（表物）</li><li><strong>Family:</strong> pollutant 污染物 / pollute 污染 / pollution 污染 / polluter 排污者</li><li><strong>Memory Tip:</strong> -ant 后缀表&quot;东西或人&quot;：pollutant 污染物、contaminant 杂质、disinfectant 消毒剂、lubricant 润滑剂。看到 -ant 先想&quot;一个具体的物&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：pollutants，与不可数的 pollution 相对。</li><li>&quot;排放污染物&quot;用 release / emit pollutants。</li><li>别把 pollutant 当&quot;污染&quot;用，它是&quot;污染物&quot;这个实体。</li></ul></div><div class="vocab-card"><h2 id="contaminate" tabindex="-1"><a class="header-anchor" href="#contaminate"><span>Contaminate</span></a></h2><p class="vc-meta"><strong>/kənˈtæmɪneɪt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>污染，弄脏（水、食物、土壤、样本）</li><li>使受污染，使不纯</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>contaminate water supplies</td><td>污染供水</td></tr><tr><td>contaminated soil</td><td>受污染的土壤</td></tr><tr><td>be contaminated with</td><td>被……污染</td></tr><tr><td>cross-contamination</td><td>交叉污染</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how leachate from the landfill contaminates groundwater.</p><blockquote><p>该示意图显示了垃圾填埋场的渗滤液如何污染地下水。</p></blockquote><p><strong>Writing Task 2</strong> Flooding can contaminate drinking water and trigger disease outbreaks.</p><blockquote><p>洪水会污染饮用水，并引发疾病暴发。</p></blockquote><p><strong>Speaking</strong> The samples were contaminated, so the results are useless.</p><blockquote><p>样本被污染了，所以结果没用。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>pollute</td><td>污染</td><td>多指大范围环境</td></tr><tr><td>taint</td><td>使变质</td><td>强调留下异味或污点</td></tr><tr><td>infect</td><td>感染</td><td>指病原体侵入生物体</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>contaminare</em>（弄脏）← <em>con-</em>（一起）+ <em>tangere</em>（接触）</li><li><strong>Family:</strong> contaminate 污染 / contamination 污染 / contaminant 污染物 / uncontaminated 未受污染的</li><li><strong>Memory Tip:</strong> con-（一起）+ tangere（接触）= 一接触就被带脏了。所以食品、水源、实验样本最常用它，强调&quot;外来物混进来了&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 con-tam-in-ate，注意中间是 -tam-。</li><li>名词是 contamination，不是 <s>contaminment</s>。</li><li>与 pollute 常可互换，但食品与医学样本固定用 contaminate。</li></ul></div><div class="vocab-card"><h2 id="deforest" tabindex="-1"><a class="header-anchor" href="#deforest"><span>Deforest</span></a></h2><p class="vc-meta"><strong>/ˌdiːˈfɒrɪst/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>砍伐森林，毁林（使某地失去森林覆盖）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>deforest an area</td><td>砍伐某地区的森林</td></tr><tr><td>deforested land</td><td>已被毁林的土地</td></tr><tr><td>large-scale deforestation</td><td>大规模毁林</td></tr><tr><td>illegal logging</td><td>非法伐木</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows land that was deforested between 1990 and 2010.</p><blockquote><p>该地图显示了 1990 至 2010 年间被砍伐森林的土地。</p></blockquote><p><strong>Writing Task 2</strong> Deforesting upland catchments increases flood risk far downstream.</p><blockquote><p>砍伐上游集水区的森林会增加下游很远处的洪涝风险。</p></blockquote><p><strong>Speaking</strong> The hills were deforested decades ago and have never recovered.</p><blockquote><p>那些山几十年前就被砍光了，至今没有恢复。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>clear-cut</td><td>皆伐</td><td>指一次性全部砍光</td></tr><tr><td>log</td><td>伐木</td><td>只指采伐，不一定清空</td></tr><tr><td>strip</td><td>剥离植被</td><td>强调地表被剥光</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>de-</em>（去除）+ <em>forest</em>（森林）</li><li><strong>Family:</strong> deforest 毁林 / deforestation 毁林（名词）/ afforest 造林 / reforest 重新造林 / forest 森林</li><li><strong>Memory Tip:</strong> 三个前缀一条线：de-（去林）、af-（造林）、re-（再造林）。写作里名词 deforestation 出现频率远高于动词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词是 deforestation，不是 <s>deforestment</s>。</li><li>&quot;滥伐&quot;常用 clear-cutting，与 deforest 不完全等同。</li><li>别写 <s>disforest</s>，该词罕用。</li></ul></div><div class="vocab-card"><h2 id="barren" tabindex="-1"><a class="header-anchor" href="#barren"><span>Barren</span></a></h2><p class="vc-meta"><strong>/ˈbærən/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>贫瘠的，不长植物的</li><li>不生育的，不孕的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>barren land</td><td>不毛之地</td></tr><tr><td>barren soil</td><td>贫瘠的土壤</td></tr><tr><td>a barren landscape</td><td>荒芜的景观</td></tr><tr><td>become barren</td><td>变得贫瘠</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows barren land where forest once stood.</p><blockquote><p>照片显示了曾经有森林覆盖的不毛之地。</p></blockquote><p><strong>Writing Task 2</strong> Intensive farming can leave once-fertile soil barren within a single generation.</p><blockquote><p>集约农业能在一代人之内让曾经的沃土变得贫瘠。</p></blockquote><p><strong>Speaking</strong> Nothing will grow there — the ground is completely barren.</p><blockquote><p>那儿什么都长不出来，地完全贫瘠了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>infertile</td><td>不肥沃的</td><td>更技术，也可指人不育</td></tr><tr><td>arid</td><td>干旱的</td><td>强调缺水，不是无产出</td></tr><tr><td>unproductive</td><td>无产出的</td><td>泛指没有收益</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>baraine</em>（贫瘠）</li><li><strong>Family:</strong> barren 贫瘠的 / barrenness 贫瘠 / barren land 荒地</li><li><strong>Memory Tip:</strong> barren 与 fertile 是标准反义对：barren land（不毛之地）↔ fertile soil（沃土）。写作里成对使用，对比鲜明。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 arid 区分：arid 讲&quot;缺水&quot;，barren 讲&quot;长不出东西&quot;。</li><li>形容人&quot;不育&quot;更常用 infertile。</li><li>比较级 barrener 罕见，多改用 more barren。</li></ul></div><div class="vocab-card"><h2 id="wilderness" tabindex="-1"><a class="header-anchor" href="#wilderness"><span>Wilderness</span></a></h2><p class="vc-meta"><strong>/ˈwɪldənəs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>荒野，无人区（未被人类开发的自然地带）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a wilderness area</td><td>荒野保护区</td></tr><tr><td>the wilderness</td><td>荒野（总称）</td></tr><tr><td>wilderness protection</td><td>荒野保护</td></tr><tr><td>in the wilderness</td><td>在荒野；（比喻）被冷落</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a wilderness area with no road access at all.</p><blockquote><p>该地图显示了一片完全没有公路通达的荒野。</p></blockquote><p><strong>Writing Task 2</strong> Only a fraction of the world&#39;s remaining wilderness is formally protected.</p><blockquote><p>世界上仅存的荒野中只有一小部分受到正式保护。</p></blockquote><p><strong>Speaking</strong> We walked for three days through pure wilderness — not a fence in sight.</p><blockquote><p>我们在真正的荒野里走了三天，连一道围栏都没看见。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>wilds</td><td>荒野</td><td>文学化，多用复数</td></tr><tr><td>wasteland</td><td>荒地</td><td>含&quot;贫瘠无用&quot;的贬义</td></tr><tr><td>backcountry</td><td>偏远地区</td><td>美式，指远离城镇的地带</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>wild</em>（野生的）+ <em>-er</em> + <em>-ness</em></li><li><strong>Family:</strong> wilderness 荒野 / wild 野生的 / wildlife 野生动物 / wildness 野生状态</li><li><strong>Memory Tip:</strong> wilderness 强调&quot;未被开发&quot;，带保护价值，褒义；wasteland 是&quot;没用的荒地&quot;，贬义。in the wilderness 还可指&quot;被边缘化&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>加冠词：the wilderness。</li><li>指原始自然区域，不是&quot;荒地&quot;（那是 wasteland）。</li><li>wildlife（野生动物）与 wilderness（荒野）只差几个字母，别混。</li></ul></div><div class="vocab-card"><h2 id="desert" tabindex="-1"><a class="header-anchor" href="#desert"><span>Desert</span></a></h2><p class="vc-meta"><strong>/ˈdezət/</strong> · noun · 名词（动词读 /dɪˈzɜːt/）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：沙漠，荒漠</li><li>动词（读音不同）：抛弃，遗弃；擅离（职守）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the Sahara Desert</td><td>撒哈拉沙漠</td></tr><tr><td>a desert climate</td><td>沙漠气候</td></tr><tr><td>desertification</td><td>荒漠化</td></tr><tr><td>a desert island</td><td>荒岛</td></tr><tr><td>desert someone</td><td>抛弃某人</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the desert advancing south by several kilometres a year.</p><blockquote><p>该地图显示沙漠每年向南推进数公里。</p></blockquote><p><strong>Writing Task 2</strong> Overgrazing accelerates desertification on the margins of drylands.</p><blockquote><p>过度放牧加速了旱地边缘的荒漠化。</p></blockquote><p><strong>Speaking</strong> Nothing survives out there — it&#39;s true desert for hundreds of miles.</p><blockquote><p>那一带什么都活不了，数百英里全是真正的沙漠。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>wasteland</td><td>荒地</td><td>强调无用，非气候类型</td></tr><tr><td>arid land</td><td>旱地</td><td>学术，指降水极少的地区</td></tr><tr><td>dunes</td><td>沙丘</td><td>指具体地貌，非区域</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>desertum</em>（被遗弃之地）← <em>deserere</em>（抛弃）</li><li><strong>Family:</strong> desert 沙漠；抛弃 / deserted 荒废的 / desertification 荒漠化 / deserter 逃兵</li><li><strong>Memory Tip:</strong> 名词重音在前 /ˈdezət/（沙漠），动词重音在后 /dɪˈzɜːt/（抛弃）。重音一变，词性就变，这是英语重音辨义的经典例子。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词与动词重音位置不同，读错会让人误解。</li><li>desert（沙漠）与 dessert（甜点）只差一个 s。</li><li>&quot;荒漠化&quot;写作 desertification，是学术文本的固定用词。</li></ul></div><div class="vocab-card"><h2 id="desolate" tabindex="-1"><a class="header-anchor" href="#desolate"><span>Desolate</span></a></h2><p class="vc-meta"><strong>/ˈdesələt/</strong> · adj · 形容词（动词读 /ˈdesəleɪt/）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>荒凉的，无人烟的</li><li>凄凉的，孤寂的</li><li>动词：使荒芜，使荒废</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a desolate landscape</td><td>荒凉的景观</td></tr><tr><td>a desolate region</td><td>荒芜的地区</td></tr><tr><td>a desolate feeling</td><td>凄凉之感</td></tr><tr><td>be left desolate</td><td>被弄得荒废</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows a desolate landscape of bare rock and salt flats.</p><blockquote><p>照片显示了一片由裸岩与盐滩构成的荒凉景观。</p></blockquote><p><strong>Writing Task 2</strong> What was once farmland now stands desolate after years of drought.</p><blockquote><p>曾经的农田在连年干旱之后如今一片荒芜。</p></blockquote><p><strong>Speaking</strong> The village felt desolate in winter — shutters closed, no one about.</p><blockquote><p>冬天的村子显得很凄凉，百叶窗都关着，一个人也没有。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>barren</td><td>贫瘠的</td><td>强调无法生长植物</td></tr><tr><td>deserted</td><td>空无一人的</td><td>强调人走了，不含荒芜感</td></tr><tr><td>bleak</td><td>荒凉的</td><td>强调阴冷、无望的气氛</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>de-</em>（完全）+ <em>solus</em>（独自）→ <em>desolare</em>（使荒芜）</li><li><strong>Family:</strong> desolate 荒凉的 / desolation 荒芜；凄凉 / solitary 孤独的 / solo 独奏</li><li><strong>Memory Tip:</strong> de-（彻底）+ solus（独自）= 连一个人都没有。同根词 solitary、solo 都是&quot;独&quot;，一条线记三个。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词读 /ˈdesələt/，动词读 /ˈdesəleɪt/，重音位置不同。</li><li>比 empty 多了&quot;荒凉+凄凉&quot;的情感色彩，别用于中性描述。</li><li>拼写 des-o-late，注意中间是 o。</li></ul></div><div class="vocab-card"><h2 id="remote" tabindex="-1"><a class="header-anchor" href="#remote"><span>Remote</span></a></h2><p class="vc-meta"><strong>/rɪˈməʊt/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>偏远的，偏僻的</li><li>遥远的（时间）；微小的（可能性）</li><li>远程的（remote control / remote sensing）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a remote area</td><td>偏远地区</td></tr><tr><td>a remote village</td><td>偏僻的村庄</td></tr><tr><td>remote sensing</td><td>遥感</td></tr><tr><td>a remote chance</td><td>极小的可能性</td></tr><tr><td>remote control</td><td>遥控</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a remote upland region with no road access.</p><blockquote><p>该地图显示了一片没有公路通达的偏远高地。</p></blockquote><p><strong>Writing Task 2</strong> Remote communities often pay more for basic goods because of transport costs.</p><blockquote><p>偏远社区常因运输成本而为基本生活物资支付更高价格。</p></blockquote><p><strong>Speaking</strong> The cottage is lovely but very remote — no phone signal at all.</p><blockquote><p>小屋很漂亮，但特别偏远，一点手机信号都没有。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>isolated</td><td>孤立的</td><td>强调与外界隔绝</td></tr><tr><td>far-flung</td><td>遥远的</td><td>书面，多形容分布广</td></tr><tr><td>inaccessible</td><td>难以到达的</td><td>强调交通不可达</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>removere</em>（移开）→ <em>remotus</em>（被移远的）</li><li><strong>Family:</strong> remote 偏远的 / remotely 稍微；远程地 / remoteness 偏远 / remove 移开</li><li><strong>Memory Tip:</strong> re-（离）+ movere（移动）= 被挪远了。remote sensing（遥感）是地理技术题的高频短语；not remotely interested 是&quot;丝毫不感兴趣&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;偏远地区&quot;常说 remote areas / regions。</li><li>remotely 有两个义：远程地（remotely controlled）与&quot;丝毫&quot;（not remotely）。</li><li>a remote chance 表&quot;极小的可能&quot;，不要按字面理解为&quot;遥远的机会&quot;。</li></ul></div><div class="vocab-card"><h2 id="distant" tabindex="-1"><a class="header-anchor" href="#distant"><span>Distant</span></a></h2><p class="vc-meta"><strong>/ˈdɪstənt/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>远的，遥远的（空间、时间）</li><li>（关系）疏远的；（神情）心不在焉的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a distant country</td><td>遥远的国度</td></tr><tr><td>in the distant past</td><td>在遥远的过去</td></tr><tr><td>a distant relative</td><td>远亲</td></tr><tr><td>distant from</td><td>远离……</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a pipeline carrying water to distant cities.</p><blockquote><p>该地图显示了向远方城市输水的管道。</p></blockquote><p><strong>Writing Task 2</strong> Goods now travel from distant regions, which raises both cost and emissions.</p><blockquote><p>如今商品来自遥远地区，这既推高了成本，也增加了排放。</p></blockquote><p><strong>Speaking</strong> He seemed distant at dinner, as if something was on his mind.</p><blockquote><p>晚饭时他显得心不在焉，好像有心事。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>far-off</td><td>遥远的</td><td>文学化，多指时间或地方</td></tr><tr><td>remote</td><td>偏远的</td><td>强调难以到达</td></tr><tr><td>faraway</td><td>远方的</td><td>口语，带遐想色彩</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>distare</em>（相隔）← <em>dis-</em>（分开）+ <em>stare</em>（站）</li><li><strong>Family:</strong> distant 远的 / distance 距离 / distantly 遥远地 / equidistant 等距的</li><li><strong>Memory Tip:</strong> dis-（分开）+ stare（站）= 分开站着，于是有了距离。distant 是形容词、distance 是名词——写作里常有人把 a long distant 写错。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 distant from，不用 <s>distant to</s>。</li><li>in the distant past / future 是固定搭配。</li><li>名词是 distance：at a distance of 5 km，不是 <s>at a distant of</s>。</li></ul></div>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};